"""Integer summaries. Python 3.11+, stdlib only.

Run: python -B numbers.py sum 2 -1 3
Check: python -B numbers.py --check
"""
import argparse
import sys

def summarize(operation, values):
    return sum(values) if operation == "sum" else len(values)

def main(args):
    parser = argparse.ArgumentParser(description=__doc__)
    parser.add_argument("operation", choices=("sum", "count"))
    parser.add_argument("values", nargs="*", type=int)
    args = parser.parse_args(args)
    return summarize(args.operation, args.values)

if __name__ == "__main__":
    if sys.argv[1:] == ["--check"]:
        assert main(["sum", "2", "-1", "3"]) == 4
        assert main(["count", "2", "-1", "3"]) == 3
        assert main(["sum"]) == 0
        assert main(["count"]) == 0
        print("4 checks passed")
    else:
        print(main(sys.argv[1:]))

