def format_receipt(cents):
    """Nonnegative integer cents to a USD receipt label."""
    if not isinstance(cents, int) or cents < 0:
        raise ValueError("cents must be a nonnegative integer")
    return f"USD {cents // 100}.{cents % 100:02d}"

