import subprocess
import sys
import unittest
from labels import label

class ContractTests(unittest.TestCase):
    def test_mapping(self):
        for status, expected in {"pending": "Waiting", "active": "In progress", "done": "Complete"}.items():
            self.assertEqual(label(status), expected)

    def test_unknown_contract(self):
        with self.assertRaises(KeyError):
            label("missing")

    def test_cli(self):
        run = subprocess.run([sys.executable, "-B", "main.py", "pending"], capture_output=True, text=True)
        self.assertEqual((run.returncode, run.stdout), (0, "Waiting\n"))
        self.assertEqual(run.stderr, "")

    def test_cli_error(self):
        run = subprocess.run([sys.executable, "-B", "main.py", "missing"], capture_output=True, text=True)
        self.assertEqual(run.returncode, 2)
        self.assertIn("invalid choice", run.stderr)
        self.assertEqual(run.stdout, "")

if __name__ == "__main__":
    unittest.main()

